package com.dlt.predictor.admin;import com.dlt.predictor.api.ApiResponse;import com.dlt.predictor.auth.*;import com.dlt.predictor.lottery.*;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/v1/admin") public class AdminController{private final AuthService users;private final DrawStore draws;AdminController(AuthService u,DrawStore d){users=u;draws=d;}@GetMapping("/users")ApiResponse<?>pending(){return ApiResponse.ok(users.pending());}@PostMapping("/users/{username}/approval")ApiResponse<Void>approval(@PathVariable String username,@RequestBody Map<String,Boolean>b){users.approve(username,Boolean.TRUE.equals(b.get("approved")));return ApiResponse.ok(null);}@PostMapping("/dlt/sync")ApiResponse<?>sync(){return ApiResponse.ok(Map.of("result","SUCCESS","insertedCount",0,"message","MVP 使用手动导入与可配置采集适配层"));}@PostMapping("/dlt/import")ApiResponse<Draw>importDraw(@RequestBody Map<String,Object>x){var f=((List<?>)x.get("frontNumbers")).stream().map(v->((Number)v).intValue()).toList();var b=((List<?>)x.get("backNumbers")).stream().map(v->((Number)v).intValue()).toList();return ApiResponse.ok(draws.upsert((String)x.get("issueNo"),LocalDate.parse((String)x.get("drawDate")),f,b));}}
